import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CTZjucLO.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-server.md","filePath":"regulament-server.md"}'),t={name:"regulament-server.md"};function u(n,e,o,c,s,p){return i(),r("div",null,[...e[0]||(e[0]=[l('<h2 id="📜-regulament-general-romana" tabindex="-1">📜 Regulament General (Română) <a class="header-anchor" href="#📜-regulament-general-romana" aria-label="Permalink to &quot;📜 Regulament General (Română)&quot;">​</a></h2><hr><h2 id="cap-1-dispozitii-generale" tabindex="-1">CAP. 1 - DISPOZIȚII GENERALE <a class="header-anchor" href="#cap-1-dispozitii-generale" aria-label="Permalink to &quot;CAP. 1 - DISPOZIȚII GENERALE&quot;">​</a></h2><h3 id="_1-1-regulamentul-serverului" tabindex="-1">1.1 Regulamentul serverului <a class="header-anchor" href="#_1-1-regulamentul-serverului" aria-label="Permalink to &quot;1.1 Regulamentul serverului&quot;">​</a></h3><p>Accesarea serverului <strong>Legacy Of CLT Roleplay</strong> implică acceptarea tuturor regulilor și procedurilor prevăzute în prezentul regulament.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Echipa <strong>Legacy Of CLT</strong> își rezervă dreptul de a actualiza, modifica sau completa regulamentul ori de câte ori este necesar.</li><li>Fiecare jucător are obligația de a verifica periodic modificările regulamentului.</li><li>Necunoașterea regulamentului nu constituie o scuză.</li><li>Administrația își rezervă dreptul de a selecta participanții care pot face parte din comunitate.</li></ul><hr><h2 id="cap-2-contul-de-joc" tabindex="-1">CAP. 2 - CONTUL DE JOC <a class="header-anchor" href="#cap-2-contul-de-joc" aria-label="Permalink to &quot;CAP. 2 - CONTUL DE JOC&quot;">​</a></h2><h3 id="_2-1-alegerea-numelui-personajului" tabindex="-1">2.1 Alegerea numelui personajului <a class="header-anchor" href="#_2-1-alegerea-numelui-personajului" aria-label="Permalink to &quot;2.1 Alegerea numelui personajului&quot;">​</a></h3><p>Numele personajului trebuie să fie realist și compatibil cu mediul Roleplay.</p><h3 id="nu-sunt-permise" tabindex="-1">Nu sunt permise <a class="header-anchor" href="#nu-sunt-permise" aria-label="Permalink to &quot;Nu sunt permise&quot;">​</a></h3><ul><li>Denumiri care conțin caractere excesive.</li><li>Combinații fără sens.</li><li>Referințe ascunse.</li><li>Elemente menite să provoace confuzie.</li></ul><h3 id="este-interzis" tabindex="-1">Este interzis <a class="header-anchor" href="#este-interzis" aria-label="Permalink to &quot;Este interzis&quot;">​</a></h3><ul><li>Utilizarea unor nume care promovează alte comunități sau servere.</li><li>Alegerea unui nume asemănător cu al altui jucător pentru inducerea în eroare.</li><li>Imitarea membrilor Staff sau a altor persoane.</li></ul><h3 id="sanctiuni" tabindex="-1">Sancțiuni <a class="header-anchor" href="#sanctiuni" aria-label="Permalink to &quot;Sancțiuni&quot;">​</a></h3><ul><li>Suspendare temporară.</li><li>În caz de repetare, suspendare permanentă.</li></ul><hr><h3 id="_2-2-identitatea-din-acte-buletin" tabindex="-1">2.2 Identitatea din acte (Buletin) <a class="header-anchor" href="#_2-2-identitatea-din-acte-buletin" aria-label="Permalink to &quot;2.2 Identitatea din acte (Buletin)&quot;">​</a></h3><p>Numele și prenumele personajului trebuie să fie realiste și potrivite mediului Roleplay.</p><h3 id="exemple-acceptate" tabindex="-1">Exemple acceptate <a class="header-anchor" href="#exemple-acceptate" aria-label="Permalink to &quot;Exemple acceptate&quot;">​</a></h3><ul><li>Andrei Popescu.</li><li>Mihai Ionescu.</li><li>Robert Dumitrescu.</li></ul><h3 id="exemple-neacceptate" tabindex="-1">Exemple neacceptate <a class="header-anchor" href="#exemple-neacceptate" aria-label="Permalink to &quot;Exemple neacceptate&quot;">​</a></h3><ul><li>Nume ale persoanelor publice.</li><li>Nume ironice sau batjocoritoare.</li><li>Combinații nerealiste sau ofensatoare.</li></ul><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Administrația poate solicita modificarea identității dacă aceasta nu respectă standardele serverului.</li><li>Refuzul modificării poate atrage sancțiuni.</li></ul><h3 id="sanctiuni-1" tabindex="-1">Sancțiuni <a class="header-anchor" href="#sanctiuni-1" aria-label="Permalink to &quot;Sancțiuni&quot;">​</a></h3><ul><li>Suspendare temporară.</li><li>Suspendare permanentă.</li></ul><hr><h3 id="_2-3-siguranta-contului" tabindex="-1">2.3 Siguranța contului <a class="header-anchor" href="#_2-3-siguranta-contului" aria-label="Permalink to &quot;2.3 Siguranța contului&quot;">​</a></h3><p>Fiecare jucător este responsabil pentru securitatea propriului cont.</p><h3 id="recomandari" tabindex="-1">Recomandări <a class="header-anchor" href="#recomandari" aria-label="Permalink to &quot;Recomandări&quot;">​</a></h3><ul><li>Utilizați o parolă complexă.</li><li>Nu divulgați datele de autentificare.</li><li>Evitați accesarea site-urilor necunoscute.</li><li>Evitați utilizarea aplicațiilor care promit avantaje în joc.</li></ul><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Echipa <strong>Legacy Of CLT</strong> nu garantează recuperarea bunurilor sau progresului pierdut în urma divulgării voluntare a datelor de acces.</li><li>Tentativele de compromitere a conturilor altor jucători reprezintă abateri grave.</li></ul><h3 id="sanctiuni-2" tabindex="-1">Sancțiuni <a class="header-anchor" href="#sanctiuni-2" aria-label="Permalink to &quot;Sancțiuni&quot;">​</a></h3><ul><li>Suspendare pe termen lung.</li><li>Suspendare permanentă a tuturor conturilor implicate.</li></ul><hr><h3 id="_2-4-partajarea-contului" tabindex="-1">2.4 Partajarea contului <a class="header-anchor" href="#_2-4-partajarea-contului" aria-label="Permalink to &quot;2.4 Partajarea contului&quot;">​</a></h3><p>Conturile sunt strict personale.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă transmiterea accesului către alte persoane.</li><li>Proprietarul contului este responsabil pentru toate acțiunile desfășurate pe contul său.</li></ul><h3 id="sanctiuni-3" tabindex="-1">Sancțiuni <a class="header-anchor" href="#sanctiuni-3" aria-label="Permalink to &quot;Sancțiuni&quot;">​</a></h3><ul><li>Suspendare temporară.</li><li>Suspendare permanentă.</li></ul><hr><h2 id="cap-3-dispozitii-finale" tabindex="-1">CAP. 3 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-3-dispozitii-finale" aria-label="Permalink to &quot;CAP. 3 - DISPOZIȚII FINALE&quot;">​</a></h2><h3 id="_3-1-aplicarea-regulamentului" tabindex="-1">3.1 Aplicarea regulamentului <a class="header-anchor" href="#_3-1-aplicarea-regulamentului" aria-label="Permalink to &quot;3.1 Aplicarea regulamentului&quot;">​</a></h3><p>Respectarea prezentului regulament este obligatorie pentru toți membrii comunității <strong>Legacy Of CLT Roleplay</strong>.</p><h3 id="reguli-4" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-4" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Toți jucătorii au obligația de a respecta regulamentul general al serverului.</li><li>Nerespectarea regulamentului poate atrage sancțiuni administrative.</li><li>Administrația își rezervă dreptul de a interpreta și aplica regulamentul în funcție de fiecare situație.</li></ul><hr><h2 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h2><p>Scopul prezentului regulament este menținerea unui mediu <strong>Roleplay</strong> organizat, echilibrat și plăcut pentru întreaga comunitate <strong>Legacy Of CLT Roleplay</strong>.</p><p>Respectarea tuturor regulilor este obligatorie pentru fiecare jucător.</p>',54)])])}const m=a(t,[["render",u]]);export{h as __pageData,m as default};
